"use client";

import { useState, useEffect, useRef, useCallback } from "react";
import Image from "next/image";
import { motion, AnimatePresence } from "framer-motion";
import { 
  User, CheckCircle, XCircle, Clock, 
  Settings, Volume2, VolumeX, Zap, Camera, ScanFace,
  QrCode, Calendar, Plus, ChevronDown, MapPin, 
  Target, Users, Info, Loader2, RefreshCw, X,
  ShieldCheck, AlertTriangle, ArrowLeft, Maximize2,
  Activity, History, Timer, Trash2, Edit2, Play, Square,
  Layers, Repeat
} from "lucide-react";
import TourGuide from "@/components/TourGuide";
import { 
    scanAbsensi, createAcara, getDaftarAcara, getLogsByAcara, 
    updateStatusKehadiran, deleteAcara, updateAcara, 
    startAcaraSession, stopAcaraSession 
} from "@/lib/actions"; 
import { Html5Qrcode } from "html5-qrcode";

const absensiTourSteps = [
    { target: '.tour-acara-header', content: 'Kelola sesi absensi aktif Anda di sini.', disableBeacon: true },
    { target: '.tour-session-controls', content: 'Klik START untuk mulai menerima absensi (bisa lebih awal dari jadwal).', },
    { target: '.tour-scanner-btn', content: 'Tombol Launch Scanner hanya aktif jika sesi sudah dimulai (ONGOING).', },
];

export default function ScanClient() {
  const [isClient, setIsClient] = useState(false);
  const [viewMode, setViewMode] = useState<'manage' | 'scanning'>('manage');
  
  // DATA STATES
  const [logs, setLogs] = useState<any[]>([]);
  const [daftarAcara, setDaftarAcara] = useState<any[]>([]);
  const [selectedAcaraId, setSelectedAcaraId] = useState<number | null>(null);
  const [scanResult, setScanResult] = useState<any>(null);
  
  // UI STATES
  const [isLoadingLogs, setIsLoadingLogs] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [modalMode, setModalMode] = useState<'create' | 'edit'>('create');
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  
  const [newAcara, setNewAcara] = useState({ 
    nama: "", tanggal: new Date().toISOString().split('T')[0], 
    lokasi: "Sekolah", waktuMulai: "07:00", waktuSelesai: "15:00",
    tipe: "SEKALI_PAKAI"
  });

  const scannerRef = useRef<Html5Qrcode | null>(null);

  // --- 1. DATA FETCHING ---
  const loadData = useCallback(async (autoSelectLatest = false) => {
    setIsLoadingLogs(true);
    try {
        const list = await getDaftarAcara();
        setDaftarAcara(list);
        
        if (list.length > 0) {
            let targetId = selectedAcaraId;
            if (autoSelectLatest || !selectedAcaraId) {
                targetId = list[0].id;
                setSelectedAcaraId(targetId);
            }
            if (targetId) {
                const dbLogs = await getLogsByAcara(targetId);
                setLogs(dbLogs.map(item => ({
                    dbId: item.id,
                    name: item.pengurus.nama,
                    role: item.pengurus.jabatan,
                    image: item.pengurus.fotoUrl,
                    time: new Date(item.tanggal).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }),
                    status: item.status,
                    scanId: item.id
                })));
            }
        } else {
            setLogs([]);
            setSelectedAcaraId(null);
        }
    } catch (err) { console.error(err); } 
    finally { setIsLoadingLogs(false); }
  }, [selectedAcaraId]);

  useEffect(() => { setIsClient(true); loadData(); }, []);

  // --- 2. SCANNER ENGINE ---
  const startScanner = async () => {
    if (!isClient || !selectedAcaraId) return;
    try {
        setTimeout(async () => {
            const element = document.getElementById("reader");
            if (!element) return;
            if (scannerRef.current) { try { await scannerRef.current.stop(); } catch (e) {} scannerRef.current = null; }
            const html5QrCode = new Html5Qrcode("reader");
            scannerRef.current = html5QrCode;
            await html5QrCode.start(
                { facingMode: "environment" }, 
                { fps: 20, qrbox: (w, h) => ({ width: Math.min(w, h) * 0.8, height: Math.min(w, h) * 0.8 }), aspectRatio: 1.0 },
                (text) => handleScan(text), () => {}
            );
        }, 300);
    } catch (err) {}
  };

  const stopScanner = async () => {
    if (scannerRef.current && scannerRef.current.isScanning) {
        await scannerRef.current.stop();
        scannerRef.current = null;
    }
  };

  useEffect(() => {
    if (viewMode === 'scanning') startScanner();
    else stopScanner();
    return () => { stopScanner(); };
  }, [viewMode, selectedAcaraId]);

  // --- 3. HANDLERS ---
  const handleScan = async (nis: string) => {
    if (!nis || scanResult || !selectedAcaraId) return;
    if (soundEnabled) new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3').play().catch(() => {});
    try {
        const result = await scanAbsensi(nis, selectedAcaraId);
        if (result.success && result.data) {
            const timestamp = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
            setScanResult({ type: 'success', data: { ...result.data, time: timestamp }, message: result.message });
            loadData(); 
        } else { setScanResult({ type: 'error', message: result.message }); }
    } catch (err) { setScanResult({ type: 'error', message: "System Error" }); }
    setTimeout(() => { setScanResult(null); }, 2000);
  };

  const handleDelete = async (id: number, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm("Hapus sesi acara ini beserta seluruh data absensinya?")) {
        await deleteAcara(id);
        setSelectedAcaraId(null);
        loadData(true);
    }
  };

  const handleOpenEdit = (acara: any, e: React.MouseEvent) => {
    e.stopPropagation();
    setModalMode('edit');
    setNewAcara({
        nama: acara.nama,
        tanggal: new Date(acara.tanggal).toISOString().split('T')[0],
        lokasi: acara.lokasi,
        waktuMulai: acara.waktuMulai ? new Date(acara.waktuMulai).toTimeString().slice(0,5) : "07:00",
        waktuSelesai: acara.waktuSelesai ? new Date(acara.waktuSelesai).toTimeString().slice(0,5) : "15:00",
        tipe: acara.tipe || "SEKALI_PAKAI"
    });
    setSelectedAcaraId(acara.id);
    setIsModalOpen(true);
  };

  const handleCreateOrUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    const formData = new FormData();
    Object.entries(newAcara).forEach(([key, val]) => formData.append(key, val));

    const res = modalMode === 'create' 
        ? await createAcara(formData) 
        : await updateAcara(selectedAcaraId!, formData);

    if (res.success) {
        setIsModalOpen(false);
        loadData(modalMode === 'create');
    }
    setIsSubmitting(false);
  };

  const handleStartSession = async () => {
    if(!selectedAcaraId) return;
    const res = await startAcaraSession(selectedAcaraId);
    if(res.success) loadData();
  };

  const handleStopSession = async () => {
    if(!selectedAcaraId) return;
    if(confirm("Akhiri sesi absensi ini? Scanner tidak akan bisa digunakan lagi untuk acara ini.")) {
        const res = await stopAcaraSession(selectedAcaraId);
        if(res.success) loadData();
    }
  };

  const handleUpdateStatus = async (absensiId: number, status: string) => {
    const res = await updateStatusKehadiran(absensiId, status);
    if(res.success) loadData();
  };

  const selectedAcara = daftarAcara.find(a => a.id === selectedAcaraId);

  // --- RENDERER: DASHBOARD ---
  const renderManagement = () => (
    <div className="flex-1 flex flex-col lg:flex-row gap-6 overflow-hidden h-full">
        
        {/* LEFT SIDEBAR */}
        <div className="w-full lg:w-80 shrink-0 flex flex-col gap-4 bg-white dark:bg-[#0f172a] border border-slate-200 dark:border-white/5 rounded-2xl p-5 shadow-sm overflow-hidden h-full">
            <div className="flex justify-between items-center px-1 mb-2">
                <h3 className="text-sm font-bold text-slate-900 dark:text-white flex items-center gap-2">
                    <History className="text-blue-600" size={18} /> Sesi Acara
                </h3>
                <button onClick={() => { setModalMode('create'); setIsModalOpen(true); }} className="p-1.5 bg-blue-600 text-white rounded-lg hover:scale-105 active:scale-95 transition-all shadow-sm">
                    <Plus size={14} strokeWidth={3} />
                </button>
            </div>
            
            <div className="flex-1 overflow-y-auto space-y-3 pr-1 custom-scrollbar">
                {daftarAcara.map((acara) => (
                    <div 
                        key={acara.id} 
                        onClick={() => setSelectedAcaraId(acara.id)}
                        className={`p-4 rounded-xl cursor-pointer transition-all border group relative ${selectedAcaraId === acara.id 
                            ? 'bg-blue-600 border-blue-400 shadow-md' 
                            : 'bg-transparent border-transparent hover:bg-slate-50 dark:hover:bg-white/5'}`}
                    >
                        <div className="flex justify-between items-start mb-2">
                            <span className={`text-[8px] font-black px-1.5 py-0.5 rounded uppercase tracking-wider ${
                                selectedAcaraId === acara.id ? 'bg-white/20 text-white' : 'bg-slate-100 text-slate-500'
                            }`}>
                                {acara.tipe?.replace('_', ' ') || 'SEKALI PAKAI'}
                            </span>
                            <div className={`flex gap-1 transition-all ${selectedAcaraId === acara.id ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                                <button onClick={(e) => handleOpenEdit(acara, e)} className={`p-1.5 rounded-lg ${selectedAcaraId === acara.id ? 'bg-white/20 hover:bg-white/30 text-white' : 'bg-slate-100 hover:bg-slate-200 text-slate-500'}`}><Edit2 size={10}/></button>
                                <button onClick={(e) => handleDelete(acara.id, e)} className={`p-1.5 rounded-lg ${selectedAcaraId === acara.id ? 'bg-red-500 hover:bg-red-600 text-white' : 'bg-red-50 hover:bg-red-100 text-red-500'}`}><Trash2 size={10}/></button>
                            </div>
                        </div>

                        <h4 className={`text-sm font-bold truncate pr-2 ${selectedAcaraId === acara.id ? 'text-white' : 'text-slate-900 dark:text-white'}`}>
                            {acara.nama}
                        </h4>
                        
                        <div className="flex justify-between items-center mt-2">
                            <p className={`text-[10px] font-medium flex items-center gap-1 ${selectedAcaraId === acara.id ? 'text-blue-100' : 'text-slate-500'}`}>
                                <Calendar size={10} /> {new Date(acara.tanggal).toLocaleDateString('id-ID')}
                            </p>
                            <span className={`text-[8px] font-black px-1.5 py-0.5 rounded uppercase ${
                                acara.status === 'ONGOING' ? 'bg-green-500 text-white' : 
                                acara.status === 'COMPLETED' ? 'bg-slate-400 text-white' : 
                                (selectedAcaraId === acara.id ? 'bg-white/20 text-white' : 'bg-blue-50 text-blue-600')
                            }`}>
                                {acara.status}
                            </span>
                        </div>
                    </div>
                ))}
            </div>
        </div>

        {/* RIGHT CONTENT */}
        <div className="flex-1 flex flex-col gap-6 overflow-hidden">
            
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-white dark:bg-[#0f172a] p-6 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm flex flex-col justify-center">
                    <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mb-1">Total Hadir</p>
                    <div className="flex items-baseline gap-2">
                        <span className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter">{logs.filter(l => l.status === 'HADIR').length}</span>
                        <span className="text-sm font-medium text-slate-400">Anggota</span>
                    </div>
                </div>
                
                <div className="md:col-span-2 flex gap-4 tour-session-controls">
                    {!selectedAcara || selectedAcara.status === 'UPCOMING' ? (
                        <button 
                            onClick={handleStartSession}
                            disabled={!selectedAcara}
                            className="flex-1 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl shadow-lg flex flex-col items-center justify-center gap-2 transition-all active:scale-95 disabled:opacity-50"
                        >
                            <Play fill="currentColor" size={24} />
                            <span className="text-sm font-bold uppercase tracking-widest">Start Session Now</span>
                        </button>
                    ) : selectedAcara.status === 'ONGOING' ? (
                        <>
                            <button 
                                onClick={() => setViewMode('scanning')}
                                className="flex-[2] bg-gradient-to-br from-blue-600 to-blue-700 p-6 rounded-2xl text-white shadow-xl flex items-center justify-between cursor-pointer hover:brightness-110 transition-all group tour-scanner-btn"
                            >
                                <div className="flex items-center gap-5">
                                    <div className="w-14 h-14 bg-white/10 rounded-xl flex items-center justify-center backdrop-blur-md"><Maximize2 size={24} /></div>
                                    <div>
                                        <h4 className="text-xl font-bold tracking-tight uppercase">Launch Scanner</h4>
                                        <p className="text-sm font-medium opacity-70">Session is Active</p>
                                    </div>
                                </div>
                                <div className="p-2 bg-white/10 rounded-lg group-hover:translate-x-1 transition-transform"><ChevronDown size={20} className="-rotate-90" /></div>
                            </button>
                            <button 
                                onClick={handleStopSession}
                                className="flex-1 bg-rose-600 hover:bg-rose-700 text-white rounded-2xl shadow-lg flex flex-col items-center justify-center gap-2 transition-all active:scale-95"
                            >
                                <Square fill="currentColor" size={24} />
                                <span className="text-sm font-bold uppercase tracking-widest">End Session</span>
                            </button>
                        </>
                    ) : (
                        <div className="flex-1 bg-slate-100 dark:bg-white/5 border border-slate-200 dark:border-white/5 rounded-2xl flex items-center justify-center text-slate-400 font-bold text-sm uppercase tracking-widest">
                            Session Completed
                        </div>
                    )}
                </div>
            </div>

            {/* LIVE ACTIVITY */}
            <div className="flex-1 bg-white dark:bg-[#0f172a] rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm flex flex-col overflow-hidden tour-activity-stream">
                <div className="p-5 border-b border-slate-100 dark:border-white/5 flex items-center justify-between bg-slate-50/50 dark:bg-transparent">
                    <h3 className="text-sm font-bold text-slate-900 dark:text-white flex items-center gap-3">
                        <Activity size={18} className="text-blue-600" /> Activity Stream
                        {isLoadingLogs && <Loader2 size={14} className="animate-spin text-blue-500" />}
                    </h3>
                    {selectedAcara?.waktuMulaiAktual && (
                        <div className="text-sm font-medium text-emerald-600 bg-emerald-50 px-3 py-1 rounded-md flex items-center gap-1.5">
                            <Timer size={14}/> Started at {new Date(selectedAcara.waktuMulaiAktual).toLocaleTimeString('id-ID', {hour:'2-digit', minute:'2-digit'})}
                        </div>
                    )}
                </div>
                <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
                    {logs.length === 0 ? (
                        <div className="h-full flex flex-col items-center justify-center opacity-20">
                            <History size={48} className="mb-3" />
                            <p className="text-sm font-medium">Belum ada aktivitas yang tercatat</p>
                        </div>
                    ) : (
                        logs.map((log) => (
                            <motion.div key={log.scanId} layout initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="flex items-center gap-4 p-3 rounded-xl bg-white dark:bg-white/5 border border-slate-100 dark:border-white/5 shadow-sm">
                                <div className="relative w-11 h-11 rounded-lg overflow-hidden shrink-0 shadow-sm border border-slate-100 dark:border-white/10"><Image src={log.image || "https://source.unsplash.com/random/100x100/?portrait"} alt={log.name} fill className="object-cover" /></div>
                                <div className="flex-1 min-w-0"><h4 className="text-sm font-bold text-slate-900 dark:text-white truncate">{log.name}</h4><p className="text-sm font-medium text-slate-500">{log.role}</p></div>
                                <div className="flex items-center gap-3">
                                    <select value={log.status} onChange={(e) => handleUpdateStatus(log.dbId, e.target.value)} className={`text-xs font-bold px-3 py-1.5 rounded-lg outline-none border transition-all ${log.status === 'HADIR' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : log.status === 'IZIN' ? 'bg-blue-50 text-blue-600 border-blue-100' : log.status === 'SAKIT' ? 'bg-amber-50 text-amber-600 border-amber-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}><option value="HADIR">HADIR</option><option value="IZIN">IZIN</option><option value="SAKIT">SAKIT</option><option value="ALPA">ALPA</option></select>
                                    <div className="text-right min-w-[60px]"><p className="text-sm font-medium text-slate-400">{log.time}</p></div>
                                </div>
                            </motion.div>
                        ))
                    )}
                </div>
            </div>
        </div>
    </div>
  );

  // --- RENDERER: SCANNER ---
  const renderScanner = () => (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[1000] bg-slate-950 flex flex-col lg:flex-row items-center justify-center p-6 gap-8">
        <button onClick={() => setViewMode('manage')} className="absolute top-8 left-8 p-4 bg-white/5 hover:bg-white/10 text-white rounded-xl backdrop-blur-xl border border-white/10 flex items-center gap-3 font-bold text-sm transition-all z-[1100]"><ArrowLeft size={18} /> Close Scanner</button>
        <div className="w-full max-w-[480px] aspect-square relative rounded-2xl overflow-hidden border-4 border-white/10 shadow-[0_0_50px_rgba(59,130,246,0.2)]">
            <div id="reader" className="absolute inset-0 z-0 [&>video]:object-cover [&>video]:h-full [&>video]:w-full"></div>
            <div className="absolute inset-0 z-20 flex flex-col items-center justify-center p-10 pointer-events-none">
                <div className="relative w-full h-full border-2 border-white/10 rounded-xl">
                    <div className="absolute -top-1 -left-1 w-12 h-12 border-t-4 border-l-4 border-blue-500 rounded-tl-lg shadow-[0_0_15px_rgba(59,130,246,0.5)]"></div>
                    <div className="absolute -top-1 -right-1 w-12 h-12 border-t-4 border-r-4 border-blue-500 rounded-tr-lg shadow-[0_0_15px_rgba(59,130,246,0.5)]"></div>
                    <div className="absolute -bottom-1 -left-1 w-12 h-12 border-b-4 border-l-4 border-blue-500 rounded-bl-lg shadow-[0_0_15px_rgba(59,130,246,0.5)]"></div>
                    <div className="absolute -bottom-1 -right-1 w-12 h-12 border-b-4 border-r-4 border-blue-500 rounded-br-lg shadow-[0_0_15px_rgba(59,130,246,0.5)]"></div>
                    {!scanResult && <motion.div animate={{ top: ["5%", "95%", "5%"] }} transition={{ duration: 2.5, repeat: Infinity, ease: "linear" }} className="absolute left-[10%] w-[80%] h-0.5 bg-blue-400 shadow-[0_0_20px_rgba(59,130,246,0.8)]"/>}
                    <AnimatePresence>{scanResult && (
                        <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0 }} className={`absolute inset-0 flex flex-col items-center justify-center text-center p-8 backdrop-blur-2xl rounded-xl z-50 pointer-events-auto ${scanResult.type === 'success' ? (scanResult.data.status === 'DUPLICATE' ? 'bg-amber-950/90' : 'bg-emerald-950/90') : 'bg-rose-950/90'}`}>
                            {scanResult.type === 'success' ? (
                                <>
                                    <div className="w-32 h-32 rounded-full p-1.5 mb-6 bg-white/10 ring-2 ring-white/20 shadow-2xl"><div className="relative w-full h-full rounded-full overflow-hidden border-2 border-white"><Image src={scanResult.data.image || "https://source.unsplash.com/random/100x100/?portrait"} alt="User" fill className="object-cover" /></div></div>
                                    <h2 className="text-2xl font-bold text-white mb-1 tracking-tight uppercase">{scanResult.data.name}</h2>
                                    <p className="text-sm font-medium text-white/50 uppercase tracking-[0.3em] mb-8">{scanResult.data.role}</p>
                                    <div className={`px-8 py-3.5 rounded-xl font-bold text-sm uppercase tracking-widest shadow-2xl bg-white ${scanResult.data.status === 'DUPLICATE' ? 'text-amber-700' : 'text-emerald-700'}`}>{scanResult.message}</div>
                                </>
                            ) : (
                                <><XCircle size={80} className="text-rose-500 mb-6" /><h2 className="text-xl font-bold text-white mb-2 uppercase">Gagal Scan</h2><p className="text-sm font-medium text-rose-200 uppercase tracking-widest bg-rose-900/50 px-6 py-3 rounded-xl border border-rose-500/30">{scanResult.message}</p></>
                            )}
                        </motion.div>
                    )}</AnimatePresence>
                </div>
            </div>
        </div>

        <div className="w-full lg:w-72 h-[350px] lg:h-[480px] bg-white/5 backdrop-blur-2xl border border-white/10 rounded-2xl p-5 flex flex-col overflow-hidden">
            <h3 className="text-sm font-bold text-blue-400 uppercase tracking-widest mb-5 flex items-center gap-2"><Activity size={16} /> Terkini</h3>
            <div className="flex-1 overflow-y-auto space-y-3 custom-scrollbar pr-1">
                {logs.slice(0, 5).map((log) => (
                    <div key={log.scanId} className="flex items-center gap-3 p-2.5 rounded-xl bg-white/5 border border-white/5">
                        <div className="relative w-9 h-9 rounded-lg overflow-hidden shrink-0"><Image src={log.image || "https://source.unsplash.com/random/100x100/?portrait"} alt="" fill className="object-cover" /></div>
                        <div className="min-w-0 flex-1"><h4 className="text-sm font-bold text-white truncate">{log.name}</h4><p className="text-[10px] font-medium text-slate-500 uppercase">{log.role}</p></div>
                    </div>
                ))}
            </div>
        </div>
    </motion.div>
  );

  return (
    <div className="h-[calc(100vh-140px)] flex flex-col gap-6 font-sans">
      <div className="flex flex-col md:flex-row justify-between items-end gap-6 mb-2 shrink-0 px-4 md:px-0">
          <div>
             <div className="flex items-center gap-4">
                <h1 className="text-3xl font-bold text-slate-900 dark:text-white tracking-tight flex items-center gap-3">Smart Attendance <span className="text-2xl p-2 bg-blue-100 dark:bg-blue-900/30 rounded-full">⚡</span></h1>
                {isClient && <TourGuide steps={absensiTourSteps} />}
             </div>
             <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mt-1">Kelola kehadiran organisasi secara efisien dan real-time.</p>
          </div>
          <div className="flex items-center gap-3">
             <button onClick={() => setSoundEnabled(!soundEnabled)} className="p-3 bg-white dark:bg-[#0f172a] border border-slate-200 dark:border-white/10 rounded-xl text-slate-500 hover:text-blue-600 shadow-sm transition-all">{soundEnabled ? <Volume2 size={18}/> : <VolumeX size={18}/>}</button>
          </div>
      </div>

      <AnimatePresence mode="wait">
        {viewMode === 'manage' ? (
            <motion.div key="manage" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="flex-1 overflow-hidden">{renderManagement()}</motion.div>
        ) : (
            <motion.div key="scanner" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 z-[1000]">{renderScanner()}</motion.div>
        ) }
      </AnimatePresence>

      {/* MODAL NEW/EDIT */}
      <AnimatePresence>
        {isModalOpen && (
            <div className="fixed inset-0 z-[2000] flex items-center justify-center p-6 backdrop-blur-md">
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setIsModalOpen(false)} className="absolute inset-0 bg-slate-900/70" />
                <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.95 }} className="relative w-full max-w-lg bg-white dark:bg-[#0f172a] rounded-2xl shadow-2xl border border-white/20 overflow-hidden">
                    <div className="p-10">
                        <div className="flex justify-between items-center mb-8">
                            <h2 className="text-xl font-bold text-slate-900 dark:text-white tracking-tight uppercase flex items-center gap-3">{modalMode === 'create' ? <Plus className="text-blue-600" /> : <Edit2 className="text-blue-600" />} {modalMode === 'create' ? 'Tambah Sesi Acara' : 'Edit Sesi Acara'}</h2>
                            <button onClick={() => setIsModalOpen(false)} className="p-2 bg-slate-100 dark:bg-white/5 rounded-lg hover:bg-rose-500 hover:text-white transition-all"><X size={20}/></button>
                        </div>
                        <form onSubmit={handleCreateOrUpdate} className="space-y-5">
                            <div className="space-y-2"><label className="text-sm font-medium text-slate-500">Nama Kegiatan</label><input required value={newAcara.nama} onChange={e => setNewAcara({...newAcara, nama: e.target.value})} type="text" placeholder="e.g. Rapat Koordinasi" className="w-full px-6 py-4 bg-slate-50 dark:bg-slate-800 rounded-xl outline-none text-sm font-medium dark:text-white border border-slate-100 dark:border-white/5 focus:border-blue-500 transition-all shadow-inner" /></div>
                            
                            <div className="space-y-2">
                                <label className="text-sm font-medium text-slate-500">Tipe Absensi</label>
                                <div className="grid grid-cols-2 gap-3">
                                    <button type="button" onClick={() => setNewAcara({...newAcara, tipe: 'SEKALI_PAKAI'})} className={`py-3 px-4 rounded-xl border flex items-center justify-center gap-2 text-xs font-bold transition-all ${newAcara.tipe === 'SEKALI_PAKAI' ? 'bg-blue-600 border-blue-600 text-white shadow-md' : 'bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-white/5 text-slate-500'}`}><Layers size={14}/> Sekali Pakai</button>
                                    <button type="button" onClick={() => setNewAcara({...newAcara, tipe: 'RUTINAN'})} className={`py-3 px-4 rounded-xl border flex items-center justify-center gap-2 text-xs font-bold transition-all ${newAcara.tipe === 'RUTINAN' ? 'bg-blue-600 border-blue-600 text-white shadow-md' : 'bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-white/5 text-slate-500'}`}><Repeat size={14}/> Rutinan</button>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2"><label className="text-sm font-medium text-slate-500">Jam Mulai</label><input required value={newAcara.waktuMulai} onChange={e => setNewAcara({...newAcara, waktuMulai: e.target.value})} type="time" className="w-full px-6 py-4 bg-slate-50 dark:bg-slate-800 rounded-xl outline-none text-sm font-medium dark:text-white border border-slate-100 dark:border-white/5 focus:border-blue-500 transition-all shadow-inner" /></div>
                                <div className="space-y-2"><label className="text-sm font-medium text-slate-500">Jam Selesai</label><input required value={newAcara.waktuSelesai} onChange={e => setNewAcara({...newAcara, waktuSelesai: e.target.value})} type="time" className="w-full px-6 py-4 bg-slate-50 dark:bg-slate-800 rounded-xl outline-none text-sm font-medium dark:text-white border border-slate-100 dark:border-white/5 focus:border-blue-500 transition-all shadow-inner" /></div>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2"><label className="text-sm font-medium text-slate-500">Tanggal</label><input required value={newAcara.tanggal} onChange={e => setNewAcara({...newAcara, tanggal: e.target.value})} type="date" className="w-full px-6 py-4 bg-slate-50 dark:bg-slate-800 rounded-xl outline-none text-sm font-medium dark:text-white border border-slate-100 dark:border-white/5 focus:border-blue-500 transition-all shadow-inner" /></div>
                                <div className="space-y-2"><label className="text-sm font-medium text-slate-500">Lokasi</label><input required value={newAcara.lokasi} onChange={e => setNewAcara({...newAcara, lokasi: e.target.value})} type="text" placeholder="Location" className="w-full px-6 py-4 bg-slate-50 dark:bg-slate-800 rounded-xl outline-none text-sm font-medium dark:text-white border border-slate-100 dark:border-white/5 focus:border-blue-500 transition-all shadow-inner" /></div>
                            </div>
                            <button disabled={isSubmitting} type="submit" className="w-full mt-4 py-5 bg-blue-600 text-white rounded-xl font-bold text-sm uppercase tracking-widest shadow-lg hover:brightness-110 active:scale-95 transition-all">{isSubmitting ? "Processing..." : (modalMode === 'create' ? 'Create Event Session' : 'Save Changes')}</button>
                        </form>
                    </div>
                </motion.div>
            </div>
        )}
      </AnimatePresence>

      <style jsx global>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #3b82f6; border-radius: 10px; }
        .dark .custom-scrollbar::-webkit-scrollbar-thumb { background: #1e293b; }
      `}</style>
    </div>
  );
}